#!/usr/bin/env bash
git_actuals() { need_cmd git || return 2; validate_target_user || return 2; GIT_ACTUAL_NAME="$(run_as_target_user git config --global user.name 2>/dev/null || true)"; GIT_ACTUAL_EMAIL="$(run_as_target_user git config --global user.email 2>/dev/null || true)"; }
git_needs() { GIT_NEED_NAME=0; GIT_NEED_EMAIL=0; git_actuals || return 2; if [ -n "$GIT_NAME" ]; then [ "$GIT_ACTUAL_NAME" = "$GIT_NAME" ] || GIT_NEED_NAME=1; else [ -n "$GIT_ACTUAL_NAME" ] || GIT_NEED_NAME=1; fi; if [ -n "$GIT_EMAIL" ]; then [ "$GIT_ACTUAL_EMAIL" = "$GIT_EMAIL" ] || GIT_NEED_EMAIL=1; else [ -n "$GIT_ACTUAL_EMAIL" ] || GIT_NEED_EMAIL=1; fi; }
git_module_check() { git_needs || return 2; [ "$GIT_NEED_NAME$GIT_NEED_EMAIL" = 00 ] && { echo "values already match"; return 0; }; echo "git identity differs or missing"; return 1; }
git_module_plan() { git_needs || return 2; if [ "$GIT_NEED_NAME" = 1 ]; then [ -n "$GIT_NAME" ] && plan_change "git user.name: \"${GIT_ACTUAL_NAME:-}\" -> \"$GIT_NAME\"" || plan_warn "git user.name missing and no desired value supplied"; else plan_ok "git user.name: ${GIT_ACTUAL_NAME}"; fi; if [ "$GIT_NEED_EMAIL" = 1 ]; then [ -n "$GIT_EMAIL" ] && plan_change "git user.email: \"${GIT_ACTUAL_EMAIL:-}\" -> \"$GIT_EMAIL\"" || plan_warn "git user.email missing and no desired value supplied"; else plan_ok "git user.email: ${GIT_ACTUAL_EMAIL}"; fi; return 0; }
git_module_apply() { git_needs || return 2; [ "$GIT_NEED_NAME" = 1 ] && [ -n "$GIT_NAME" ] && run_as_target_user git config --global user.name "$GIT_NAME"; [ "$GIT_NEED_EMAIL" = 1 ] && [ -n "$GIT_EMAIL" ] && run_as_target_user git config --global user.email "$GIT_EMAIL"; [ "$GIT_NEED_NAME$GIT_NEED_EMAIL" = 00 ] && echo "values already match" || echo "git identity updated"; }
